import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';
import {} from '@/primitives';
import {} from '@/text';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;
  const root = new Group();

  // Store disposables and timelines for cleanup
  const disposables = [];
  const timelines = [];

  // Create plane geometry and basic material
  const geometry = new PlaneGeometry(1, 1);
  const material = new MeshBasicNodeMaterial();
  const mesh = new Mesh(geometry, material);
  root.add(mesh);

  // Load texture if an image URL is provided
  const imageUrl = config.imageUrl ?? config.meshUrl ?? null;
  let loadedTexture = null;
  if (imageUrl) {
    ctx.textureLoader.loadTexture(imageUrl).then((tex) => {
      loadedTexture = tex;
      material.map = tex;
      material.needsUpdate = true;
      disposables.push(() => {
        if (tex?.dispose) tex.dispose();
      });
    });
  }

  // Apply cinematic primitives defined in config
  const primitiveInstances = [];
  const primitives = config.cinematicPrimitives ?? [];
  for (const prim of primitives) {
    const name = prim.name;
    const params = prim.params || {};
    const instance = ctx.primitives[name](root, params);
    primitiveInstances.push(instance);
    if (instance?.timeline) timelines.push(instance.timeline);
  }

  // Render any text items using the font atlas
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  for (const item of items) {
    const textNode = ctx.fontAtlas.createText(item.text, {
      fontSize: item.typography?.fontSize,
      color: item.typography?.color ?? '#e8ecf2',
      align: 'left',
    });
    root.add(textNode);
  }

  // Prepare userData for event handlers and cleanup
  root.userData.handlers = {};

  root.userData.cleanup = () => {
    // Cleanup primitives
    for (const inst of primitiveInstances) {
      if (inst?.cleanup) inst.cleanup();
    }
    // Kill GSAP timelines
    for (const tl of timelines) {
      tl.kill();
    }
    // Dispose geometry, material, and texture
    if (geometry?.dispose) geometry.dispose();
    if (material?.dispose) material.dispose();
    if (loadedTexture?.dispose) loadedTexture.dispose();
    // Run any additional disposables
    for (const fn of disposables) fn();
  };

  return root;
}
